use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;

const NO_PROJECT: &str = "No Project";

pub struct StatsCommand;

impl StatsCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;

        for (duration, name) in project_totals(&entries) {
            println!("{}  {name}", utilities::format_duration_compact(duration));
        }

        let total = entries
            .iter()
            .filter(|entry| !entry.is_running())
            .map(|entry| entry.duration)
            .sum();
        println!("{}  Total", utilities::format_duration_compact(total));
        Ok(())
    }
}

fn project_totals(entries: &[TimeEntry]) -> Vec<(i64, String)> {
    let mut totals = HashMap::<String, i64>::new();
    for entry in entries.iter().filter(|entry| !entry.is_running()) {
        let name = entry
            .project
            .as_ref()
            .map(|project| project.name.clone())
            .unwrap_or_else(|| NO_PROJECT.to_string());
        *totals.entry(name).or_default() += entry.duration;
    }

    let mut totals: Vec<_> = totals
        .into_iter()
        .map(|(name, duration)| (duration, name))
        .collect();
    totals.sort_by(|(duration_a, name_a), (duration_b, name_b)| {
        duration_b.cmp(duration_a).then_with(|| name_a.cmp(name_b))
    });
    totals
}

